List<String> wordsString(String s) {
  if (s.isEmpty) {
    return [];
  }

  List<String> sList = [];

  for (int i = 0; i < s.length; i++) {
    String letter = s[i];
    if (letter == ',') {
      sList.add(' ');
    } else {
      sList.add(letter);
    }
  }

  String joined = sList.join('');
  return joined.split(RegExp(r'\s+')).where((word) => word.isNotEmpty).toList();
}

