List<int> uniqueDigits(List<int> x) {
  List<List<int>> digits = [];

  for (var i in x) {
    var list = [i];

    while (list.length > 1) {
      if (!digits.contains(list)) {
        digits.add(list);
      } else {
        break;
      }

      var newDigit = 0;

      int count = 0;

      for (var j in list) {
        var tmp = j % 10;
        if (++count == list.length - 1 && tmp != 0) {
          continue;
        }

        if (tmp >= 5) {
          newDigit += tmp - 5;
        } else {
          newDigit += tmp + 5;
        }
      }

      list.removeLast();
      list.insert(0, newDigit ~/ 9);
    }
  }

  return digits.map((l) => l.reduce((a,b)=> a+b)).toList()..sort();
}

