import 'dart:math';

@pragma('vm:entry-point')
num doAlgebra(List<String> operator, List<int> operand) {
  List<num> values = List<num>.from(operand);
  List<String> ops = List<String>.from(operator);

  // Handle exponentiation first (highest precedence)
  int i = 0;
  while (i < ops.length) {
    if (ops[i] == '**') {
      values[i] = pow(values[i], values[i + 1]);
      values.removeAt(i + 1);
      ops.removeAt(i);
    } else {
      i++;
    }
  }

  // Handle multiplication and floor division (medium precedence)
  i = 0;
  while (i < ops.length) {
    if (ops[i] == '*') {
      values[i] = values[i] * values[i + 1];
      values.removeAt(i + 1);
      ops.removeAt(i);
    } else if (ops[i] == '//') {
      values[i] = (values[i] ~/ values[i + 1]).toInt();
      values.removeAt(i + 1);
      ops.removeAt(i);
    } else {
      i++;
    }
  }

  // Handle addition and subtraction (lowest precedence)
  i = 0;
  while (i < ops.length) {
    if (ops[i] == '+') {
      values[i] = values[i] + values[i + 1];
      values.removeAt(i + 1);
      ops.removeAt(i);
    } else if (ops[i] == '-') {
      values[i] = values[i] - values[i + 1];
      values.removeAt(i + 1);
      ops.removeAt(i);
    } else {
      i++;
    }
  }

  return values[0];
}

@pragma('vm:entry-point')
void main() {
  // Test case 1: 2 + 3 * 4 - 5 = 9
  print(doAlgebra(['+', '*', '-'], [2, 3, 4, 5])); // Expected: 9

  // Test case 2: 2 * 3 + 4 = 10
  print(doAlgebra(['*', '+'], [2, 3, 4])); // Expected: 10

  // Test case 3: 10 - 5 = 5
  print(doAlgebra(['-'], [10, 5])); // Expected: 5

  // Test case 4: 2 ** 3 = 8
  print(doAlgebra(['**'], [2, 3])); // Expected: 8

  // Test case 5: 10 // 3 = 3
  print(doAlgebra(['//'], [10, 3])); // Expected: 3

  // Test case 6: 2 ** 3 * 4 = 32
  print(doAlgebra(['**', '*'], [2, 3, 4])); // Expected: 32

  // Test case 7: 100 // 10 + 5 = 15
  print(doAlgebra(['//', '+'], [100, 10, 5])); // Expected: 15
}

